const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const date = yesterday.toISOString().split('T')[0]; // "2026-05-07"
const dateForFile = date.replace(/-/g, '_');         // "2026_05_07"

const parts = date.split('-');
const curatedPath = `${parts[0]}/${parts[1]}/${parts[2]}/datos.csv`; // "2026/05/07/datos.csv"

return [{
  json: { date, dateForFile, curatedPath }
}];

const all = $input.all();

// item 0 = HTTP Request (OpenMeteo), item 1 = HTTP Request1 (Madrid)
const omData = JSON.parse(all[0].json.data);
const madData = JSON.parse(all[1].json.data);

// Mapa hora -> fila openmeteo
const omByHour = {};
omData.forEach(row => {
  const hour = row.datetime.substring(11, 13);
  omByHour[hour] = row;
});

// Cabecera CSV
const csvHeaders = [
  'fecha', 'hora',
  'temperatura_c', 'humedad_pct', 'viento_kmh',
  'presion_hpa', 'precipitacion_mm',
  'madrid_magnitud', 'madrid_estacion'
];

const csvRows = [csvHeaders.join(',')];

for (let h = 0; h < 24; h++) {
  const hourStr = String(h).padStart(2, '0');
  const om = omByHour[hourStr] ?? {};
  const madKey = `H${String(h + 1).padStart(2, '0')}`;
  const mad = madData[0] ?? {};

  const row = [
    om.date ?? '',
    hourStr,
    om.temperature_2m ?? '',
    om.relative_humidity_2m ?? '',
    om.windspeed_10m ?? '',
    om.surface_pressure ?? '',
    om.precipitation ?? '',
    mad.MAGNITUD ?? '',
    mad.ESTACION ?? ''
  ];

  csvRows.push(row.join(','));
}

// Ruta curated
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);
const parts = yesterday.toISOString().split('T')[0].split('-');
const curatedPath = `${parts[0]}/${parts[1]}/${parts[2]}/datos.csv`;

return [{
  json: {
    path: curatedPath,
    content: csvRows.join('\n')
  }
}];
